const perfil = $input.first().json;
const helpers = this.helpers;
const MODALIDADES = { pregao_eletronico: 6, dispensa: 8 };

const hoje = new Date();
const ontem = new Date(hoje.getTime() - 24 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10).replace(/-/g, '');
const dataInicial = fmt(ontem);
const dataFinal = fmt(hoje);

// retry com backoff fixo -- absorve instabilidades passageiras da API do PNCP
// (confirmado ao vivo: 503 "Service Unavailable" que se resolveu sozinho minutos
// depois). So retenta erro de transporte/servidor, nao ha nada a ganhar retentando
// uma URL malformada -- mas como a URL e sempre montada aqui mesmo com dados
// validos, qualquer falha e tratada igual (erro de rede/servidor e o caso comum).
async function fetchComRetry(url, tentativas, esperaMs) {
  let ultimoErro = null;
  for (let i = 0; i < tentativas; i++) {
    try {
      return await helpers.httpRequest({ method: 'GET', url, json: true });
    } catch (e) {
      ultimoErro = e;
      if (i < tentativas - 1) await new Promise((r) => setTimeout(r, esperaMs));
    }
  }
  const erro = new Error((ultimoErro && ultimoErro.message) || 'Erro desconhecido na consulta ao PNCP');
  erro.original = ultimoErro;
  throw erro;
}

const modalidadesPerfil = Array.isArray(perfil.modalidades) ? perfil.modalidades : [];
const consultas = [];

for (const m of modalidadesPerfil) {
  const codigo = MODALIDADES[m];
  if (!codigo) continue;

  const baseUrl = 'https://pncp.gov.br/api/consulta/v1/contratacoes/publicacao?dataInicial=' + dataInicial +
    '&dataFinal=' + dataFinal + '&codigoModalidadeContratacao=' + codigo + '&tamanhoPagina=50';

  let registros = [];
  let erroApi = false;
  let erroApiDetalhe = null;

  try {
    const pagina1 = await fetchComRetry(baseUrl + '&pagina=1', 3, 3000);
    registros = registros.concat((pagina1 && pagina1.data) || []);
    const totalPaginas = Math.min((pagina1 && pagina1.totalPaginas) || 1, 150);
    for (let p = 2; p <= totalPaginas; p++) {
      const paginaN = await fetchComRetry(baseUrl + '&pagina=' + p, 3, 3000);
      registros = registros.concat((paginaN && paginaN.data) || []);
    }
  } catch (e) {
    erroApi = true;
    erroApiDetalhe = e.message;
  }

  consultas.push({
    perfil_id: perfil.perfil_id,
    nome_perfil: perfil.nome_perfil,
    whatsapp_numero: perfil.whatsapp_numero,
    palavras: perfil.objeto_palavras_chave || [],
    valor_min: perfil.valor_min,
    valor_max: perfil.valor_max,
    uf: perfil.uf || [],
    municipio: perfil.municipio || [],
    tipo_perfil: perfil.tipo_perfil,
    usuario_id: perfil.usuario_id,
    modalidade_codigo: codigo,
    dataInicial,
    dataFinal,
    data: registros,
    erro_api: erroApi,
    erro_api_detalhe: erroApiDetalhe
  });
}

return consultas.map((json) => ({ json }));

function normalizar(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const combinados = $input.all();
const resultados = [];
let consultasComErro = 0;

for (const item of combinados) {
  const consulta = item.json;
  if (consulta.erro_api) consultasComErro++;
  const registros = consulta.data || [];
  const palavrasNorm = (consulta.palavras || []).map(normalizar).filter(Boolean);
  const ufsPerfil = consulta.uf || [];
  const municipiosNorm = (consulta.municipio || []).map(normalizar).filter(Boolean);

  for (const r of registros) {
    const objetoNorm = normalizar(r.objetoCompra);
    const bateuPalavra = palavrasNorm.some(p => objetoNorm.includes(p));
    if (!bateuPalavra) continue;

    const valor = r.valorTotalEstimado != null ? Number(r.valorTotalEstimado) : null;
    if (consulta.valor_min != null && (valor == null || valor < consulta.valor_min)) continue;
    if (consulta.valor_max != null && (valor == null || valor > consulta.valor_max)) continue;

    const uf = r.unidadeOrgao ? r.unidadeOrgao.ufSigla : null;
    if (ufsPerfil.length && !ufsPerfil.includes(uf)) continue;

    const municipio = r.unidadeOrgao ? r.unidadeOrgao.municipioNome : null;
    if (municipiosNorm.length && !municipiosNorm.includes(normalizar(municipio))) continue;

    const cnpj = (r.orgaoEntidade && r.orgaoEntidade.cnpj) || (r.orgaoSubRogado && r.orgaoSubRogado.cnpj) || '';
    const link = 'https://pncp.gov.br/app/editais/' + cnpj + '/' + r.anoCompra + '/' + r.sequencialCompra;

    resultados.push({
      perfil_id: consulta.perfil_id,
      nome_perfil: consulta.nome_perfil,
      whatsapp_numero: consulta.whatsapp_numero,
      pncp_id: r.numeroControlePNCP,
      objeto: r.objetoCompra,
      orgao: (r.orgaoEntidade && r.orgaoEntidade.razaoSocial) || '',
      valor,
      uf,
      municipio,
      modalidade_nome: r.modalidadeNome,
      link,
      data_abertura_proposta: r.dataAberturaProposta || null,
      data_encerramento_proposta: r.dataEncerramentoProposta || null,
      tipo_perfil: consulta.tipo_perfil,
      usuario_id: consulta.usuario_id
    });
  }
}
// envelope (1 item sempre) -- ver nota abaixo sobre o gotcha de 0 itens matando o loop
return [{ json: { resultados, consultasComErro, totalConsultas: combinados.length } }];

const candidatos = $('Expandir Resultados Filtrados').all().map(i => i.json);
const jaEnviados = new Set($input.all().map(i => i.json && i.json.pncp_id).filter(Boolean));
// dedup tambem DENTRO do proprio lote (defensivo -- alem de contra o que ja esta
// registrado no banco, nunca manda o mesmo pncp_id duas vezes no mesmo ciclo,
// mesmo que ele apareca repetido nos candidatos por algum motivo upstream).
const vistosNesteLote = new Set();
const novos = [];
for (const c of candidatos) {
  if (jaEnviados.has(c.pncp_id)) continue;
  if (vistosNesteLote.has(c.pncp_id)) continue;
  vistosNesteLote.add(c.pncp_id);
  novos.push(c);
}
return [{ json: { novos } }];

// BUG REAL DE PRODUCAO (confirmado 14/08: perfil do Jonas achou 6 editais novos
// no mesmo ciclo, mas so 1 mensagem foi enviada): esse node usava $input.first(),
// que pega so o PRIMEIRO item recebido e descarta o resto silenciosamente. Como
// "Enviar Edital WhatsApp" e "Registrar Envio" (nodes nao-Code) rodam automaticamente
// uma vez por item de entrada, bastava esse Code node devolver 1 item so pra travar
// o ciclo inteiro em "no maximo 1 notificacao por perfil a cada 3h", nao importa
// quantas licitacoes novas realmente existissem. Corrigido pra processar TODOS os
// itens recebidos (uma mensagem por licitacao nova).
function formataValor(v) {
  if (v == null) return 'valor nao informado';
  return 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
}
return $input.all().map(({ json: item }) => {
  const texto = 'Nova licitacao para o alerta "' + item.nome_perfil + '":\n\n' +
    item.objeto.slice(0, 300) + (item.objeto.length > 300 ? '...' : '') + '\n\n' +
    'Orgao: ' + item.orgao + '\n' +
    'Valor estimado: ' + formataValor(item.valor) + '\n' +
    'Modalidade: ' + item.modalidade_nome + '\n' +
    (item.municipio ? ('Local: ' + item.municipio + '/' + item.uf + '\n') : '') +
    '\nEdital: ' + item.link;
  return { json: { ...item, numero: item.whatsapp_numero.replace(/\D/g, ''), texto } };
});
